import{_ as s,o as t,c as e,a2 as i}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Tags","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/tags.md","filePath":"concepts/tags.md","lastUpdated":1784611952000}'),n={name:"concepts/tags.md"};function l(p,a,o,h,r,d){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h1><p>A tag is a category that groups related endpoints within a collection. Tags may or may not exist — not all collections have them, and a collection can have any number of tags.</p><p>Tags come from the OpenAPI/Swagger/Postman file itself. There are <strong>no YAML config settings</strong> for tags — you cannot create, rename, or delete tags in <code>swag2mcp.yaml</code>. The only way to change tags is to edit the original spec file.</p><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec (domain, e.g. &quot;meteo&quot;)</span></span>
<span class="line"><span>  └── Collection (spec file, e.g. forecast.yml)</span></span>
<span class="line"><span>        └── Tag &quot;weather&quot;</span></span>
<span class="line"><span>              └── GET /forecast</span></span>
<span class="line"><span>              └── GET /forecast/hourly</span></span>
<span class="line"><span>        └── Tag &quot;alerts&quot;</span></span>
<span class="line"><span>              └── GET /alerts</span></span></code></pre></div><h2 id="how-tags-are-created" tabindex="-1">How Tags Are Created <a class="header-anchor" href="#how-tags-are-created" aria-label="Permalink to &quot;How Tags Are Created&quot;">​</a></h2><p>Tags are extracted from the spec document during parsing:</p><p><strong>OpenAPI 3.x / Swagger 2.0</strong> — each operation&#39;s <code>tags</code> list becomes tags:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">paths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  /pet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      summary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Find pet by ID&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    post</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      summary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Add a new pet&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  /pet/{petId}/uploadImage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    post</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pet_images&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      summary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Uploads an image&quot;</span></span></code></pre></div><p><strong>Postman</strong> — each top-level folder becomes a tag. Nested folders use the last folder name.</p><p>If an endpoint has no tags, it is placed under a <code>&quot;default&quot;</code> tag.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Tags help the LLM find groups of related endpoints. Instead of searching through every endpoint in a collection, the LLM can first find the right tag, then list only the endpoints within it.</p><h2 id="mcp-tools-for-tags" tabindex="-1">MCP Tools for Tags <a class="header-anchor" href="#mcp-tools-for-tags" aria-label="Permalink to &quot;MCP Tools for Tags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>tag_by_spec</code></td><td>All tags across an entire spec</td></tr><tr><td><code>tag_by_collection</code></td><td>Tags within a specific collection</td></tr><tr><td><code>tag_by_id</code></td><td>Tag details (title, method count)</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Endpoints grouped under a tag</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Query: &quot;Show all tags in the pet collection&quot;</span></span>
<span class="line"><span>→ tag_by_collection(collectionId: &quot;...&quot;)</span></span>
<span class="line"><span>→ Result: pets (5 methods), pet_images (1 method)</span></span></code></pre></div><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>Tags are read-only from the config perspective. To add, rename, or remove tags, edit the original OpenAPI/Swagger/Postman file and run <code>swag2mcp update</code>.</li><li>Tags cannot be filtered or disabled per-collection in the YAML config.</li></ul>`,19)])])}const k=s(n,[["render",l]]);export{g as __pageData,k as default};
